package com.spai.portal.audit.controller;import com.spai.portal.audit.domain.AuditLog;import com.spai.portal.audit.repository.AuditLogRepository;import com.spai.portal.common.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/admin/audits")@PreAuthorize("hasRole('ADMIN')")public class AuditController{private final AuditLogRepository logs;public AuditController(AuditLogRepository logs){this.logs=logs;}@GetMapping public ApiResponse<PageResponse<AuditLog>>list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){Page<AuditLog>p=logs.findAll(PageRequest.of(page,Math.min(size,100),Sort.by(Sort.Direction.DESC,"createdAt")));return ApiResponse.ok(new PageResponse<AuditLog>(p.getContent(),page,size,p.getTotalElements()));}}
